---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

hl.bind(mainMod .. " + period", hl.dsp.layout("move +col"))
hl.bind(mainMod .. " + comma", hl.dsp.layout("move -col"))

-- Layout / window arrangement helpers -----------------------------------------
local function activeLayout()
    return hl.get_config("general:layout") or "dwindle"
end

local function toggleLayout()
    local nextLayout = activeLayout() == "scrolling" and "dwindle" or "scrolling"
    hl.config({ general = { layout = nextLayout } })
    hl.exec_cmd("~/.config/hypr/scripts/layout-notify " .. nextLayout)
    return { ok = true }
end

local function moveFocusedWindow(direction)
    hl.dispatch(hl.dsp.window.move({ direction = direction }))
    return { ok = true }
end

-- Scrolling layout: make the focused column half-width and move it to the far left.
local function shrinkAndDockLeft()
    if activeLayout() ~= "scrolling" then
        return { ok = true }
    end

    hl.dispatch(hl.dsp.layout("colresize 0.5"))

    -- wrap_swapcol is disabled, so repeating this parks the column at index 0.
    for _ = 1, 32 do
        hl.dispatch(hl.dsp.layout("swapcol l"))
    end

    return { ok = true }
end

local function vimMove(direction)
    if activeLayout() == "scrolling" then
        if direction == "up" or direction == "down" then
            return shrinkAndDockLeft()
        end

        hl.dispatch(hl.dsp.layout(direction == "left" and "swapcol l" or "swapcol r"))
        return { ok = true }
    end

    return moveFocusedWindow(direction)
end

local function scrollMove(direction)
    if activeLayout() == "scrolling" then
        hl.dispatch(hl.dsp.layout(direction == "left" and "swapcol l" or "swapcol r"))
    end

    return { ok = true }
end

local function toggleSplit()
    if activeLayout() ~= "scrolling" then
        hl.dispatch(hl.dsp.layout("togglesplit"))
    end

    return { ok = true }
end


-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())

-- Switch between dwindle and scrolling layouts.
hl.bind(mainMod .. " + L", toggleLayout)

-- Searchable keybindings overlay (same data as the PDF).
hl.bind(mainMod .. " + SLASH",
    hl.dsp.exec_cmd("~/.config/hypr/scripts/show-keybinds"))

-- Vim-style window movement.
-- Dwindle: Super+Shift+H/J/K/L moves the focused window.
-- Scrolling: H/L move between columns; J/K shrink the column and dock it left.
hl.bind(mainMod .. " + SHIFT + H", function() return vimMove("left") end)
hl.bind(mainMod .. " + SHIFT + J", function() return vimMove("down") end)
hl.bind(mainMod .. " + SHIFT + K", function() return vimMove("up") end)
hl.bind(mainMod .. " + SHIFT + L", function() return vimMove("right") end)

-- Scrolling layout: Alt+H/L move the focused window left/right.
hl.bind(mainMod .. " + ALT + H", function() return scrollMove("left") end)
hl.bind(mainMod .. " + ALT + L", function() return scrollMove("right") end)

-- Dwindle: split toggle (moved off Super+J).
hl.bind(mainMod .. " + ALT + J", toggleSplit)

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Scrolling layout column width presets.
hl.bind(mainMod .. " + plus", hl.dsp.layout("colresize +conf"))
hl.bind(mainMod .. " + minus", hl.dsp.layout("colresize -conf"))
-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + p", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })

-- Screenshot keybindings (Hyprshot)

-- Select a particular screen region
hl.bind(mainMod .. " + SHIFT + S",
    hl.dsp.exec_cmd("hyprshot -m region"))

-- Select a particular window
hl.bind(mainMod .. " + PRINT",
    hl.dsp.exec_cmd("hyprshot -m window"))

-- Lock screen
