-- Frost the translucent rofi launcher.
-- ignore_alpha keeps the blur from bleeding past the rounded corners.
hl.layer_rule({
    name         = "rofi-frost",
    match        = { namespace = "^rofi$" },
    blur         = true,
    blur_popups  = true,
    ignore_alpha = 0.2,
    animation    = "popin 85%",
})

-- Frost swaync's notification popups and control center too.
hl.layer_rule({
    name         = "swaync-frost",
    match        = { namespace = "^swaync" },
    blur         = true,
    blur_popups  = true,
    ignore_alpha = 0.2,
    animation    = "popin 90%",
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

